try:
    from collections.abc import Mapping
except ImportError:
    from collections import Mapping
from collections import OrderedDict, defaultdict, namedtuple
from copy import copy

from six.moves import configparser
from ta_emil_cli_aatrace_parser.tracecollector import TraceCollector

from .aashell import get_cell_mapping, get_running_nodes_details
from .exceptions import (
    CellNotConnected,
    MissingKeyNodeField,
    NodeDoesNotExist,
    PlatformNotSupported,
    WrongNodeAttribute,
)
from .logger_config import log

NODES_INI = "/home/ute/btslog2/nodes.ini"
AIRSCALE_PLATFORMS = ["FSMr4", "LF_Al", "Loki_", "LokiA", "LokiB", "ThorA"]
COMPONENTS = [
    "UEC",
    "CELLC",
    "MACCELL",
    "MACULTTI",
    "MACDLTTI",
    "TUPU",
    "DL-PHY",
    "UL-PHY",
    "LOM",
    "ENBC",
    "MCEC",
    "TUPc",
    "RROM",
    "BBCUTIL",
    "BTSOM",
]
RECEIVER_MSG_TASK = "0x60a"
SENDER_MSG_TASK = "0x31d"
SENDER_CPU = "0x11"
FSMR3_BOARD = "0x10"

NODE_DEFAULTS = OrderedDict()
NODE_DEFAULTS["Connection"] = "TCP"
NODE_DEFAULTS["IPAddress"] = "192.168.255.1"
NODE_DEFAULTS["Board"] = None
NODE_DEFAULTS["CPU"] = None
NODE_DEFAULTS["Task"] = "0x0"
NODE_DEFAULTS["Port"] = "BTSLOG"
NODE_DEFAULTS["EchoTask"] = "0x0300"
NODE_DEFAULTS["MsgTask"] = RECEIVER_MSG_TASK
NODE_DEFAULTS["RadTask"] = "0x60c"
NODE_DEFAULTS["Type"] = "WCDMA"

KEY_NODE_FIELDS = ["Board", "CPU"]
NODE = namedtuple("node", NODE_DEFAULTS.keys())


def create_receiver_nodes(nodes_struct=None, ignore_not_connected_cells=False):
    """to be created"""
    hw_config = _get_nodes_hw_adresses(ignore_not_connected_cells)

    if not nodes_struct:
        return create_nodes_from_hw_config(hw_config)
    elif isinstance(nodes_struct, list):
        return create_nodes_from_list(nodes_struct)
    elif isinstance(nodes_struct, Mapping):
        return create_nodes_from_dict(nodes_struct)
    else:
        raise TypeError("Could not create nodes from type %s" % type(nodes_struct))


def create_nodes_from_hw_config(hw_config):
    """to be created"""
    nodes = {}
    for node_name, nodes_addresses in hw_config.items():
        nodes.update(_create_nodes_by_nodes_addresses(node_name, nodes_addresses))
    return nodes


def create_nodes_from_list(nodes_names):
    """to be created"""
    nodes_config = _read_nodes_config()
    nodes = {}
    for node_name in nodes_names:
        node_dict = _get_node_default_config()
        try:
            node_config_list = nodes_config.items(section=node_name)
        except configparser.NoSectionError:
            raise NodeDoesNotExist(
                "Node '%s' does not exist in '%s'." % (node_name, NODES_INI)
            )

        for name, value in node_config_list:
            if name in node_dict:
                node_dict[name] = value
            else:
                pass  # Log here
        _check_fields_are_filled_and_update_nodes(nodes, node_name, node_dict)
    return nodes


def create_nodes_from_dict(nodes_dict):
    """to be created"""
    nodes = {}
    for node_name, node_attrs in nodes_dict.items():
        node_dict = _get_node_default_config()
        for attr_name, attr_value in node_attrs.items():
            if attr_name in node_dict:
                node_dict[attr_name] = attr_value
            else:
                raise WrongNodeAttribute(
                    "Creating node from provided dictionary '{}' failed."
                    "Node can only have following attributes: {}".format(
                        nodes_dict, NODE_DEFAULTS.keys()
                    )
                )
        _check_fields_are_filled_and_update_nodes(nodes, node_name, node_dict)
    return nodes


def create_sender_node():
    """to be created"""
    platform, uec_core_ids = TraceCollector.get_hw_platform_and_core_ids_for_uec()
    node_details = get_running_nodes_details()
    node_dict = _get_node_default_config()
    if platform in AIRSCALE_PLATFORMS:
        master_nid = node_details[0][
            "masterNid"
        ]  # assumption: masterNid is the same for all nodes so we can take first
        master_node_address = _get_cpu_from_node_address(master_nid)
        master_node_board = _get_board_from_node_address(master_nid)
        node_dict["Board"] = master_node_board
        node_dict["CPU"] = master_node_address
        node_dict["MsgTask"] = SENDER_MSG_TASK
        node_tuple = NODE(**node_dict)
        return node_tuple
    elif platform == "FSMr3":
        node_dict["Board"] = FSMR3_BOARD
        node_dict["CPU"] = SENDER_CPU
        node_dict["MsgTask"] = SENDER_MSG_TASK
        node_tuple = NODE(**node_dict)
        return node_tuple
    else:
        raise PlatformNotSupported("Platform: %s" % platform)


def format_hex(num):
    """
    Removes leading 0x from hex number and adds leading zero if number has odd number of digits:
    0x2015A -> 02015a
    or return passed string if its not a hexadecimal.
    """
    try:
        int(num, 16)
    except ValueError:
        return num
    num = num.split("0x")[-1]
    to_pad = len(num) if len(num) % 2 == 0 else (len(num) + 1)
    return ("{:0%sX}" % to_pad).format(int(num, 16)).lower()


def check_cells_are_connected(cell_mapping, ignore_not_connected_cells):
    """to be created"""
    for cell_id, cell_config in cell_mapping.items():
        for component_name in COMPONENTS:
            try:
                _check_cell_connected(cell_id, cell_config, component_name)
            except CellNotConnected:
                if ignore_not_connected_cells:
                    log.warn(
                        "Cell '{}' component '{}' not connected.".format(
                            cell_id, component_name
                        )
                    )
                    return
                raise CellNotConnected(
                    "Cell '{}' component '{}' not connected. "
                    "All cells platform info from aaShell: {}".format(
                        cell_id, component_name, cell_mapping
                    )
                )


def _get_nodes_hw_adresses(ignore_not_connected_cells):
    node_name_to_hw_address = defaultdict(set)
    cell_mapping = get_cell_mapping()
    check_cells_are_connected(cell_mapping, ignore_not_connected_cells)
    node_details = get_running_nodes_details()
    _parse_node_details_into_node_name_to_hw_address_dict(
        node_details, node_name_to_hw_address
    )
    _parse_cell_mapping_into_node_name_to_hw_address_dict(
        cell_mapping, node_name_to_hw_address
    )
    return node_name_to_hw_address


def _parse_node_details_into_node_name_to_hw_address_dict(node_details, target_dict):
    for component_name in COMPONENTS:
        for node in node_details:
            processes = node["Running processes"]
            node_id = node["ownNid"]
            for process_name in processes:
                if process_name.startswith(component_name):
                    target_dict[component_name].add(node_id)


def _parse_cell_mapping_into_node_name_to_hw_address_dict(cell_mapping, target_dict):
    for component_name in COMPONENTS:
        for cell_map in cell_mapping.values():
            for elem_name, elem_value in cell_map.items():
                if elem_name.startswith(component_name):
                    target_dict[component_name].add(elem_value)


def _check_fields_are_filled_and_update_nodes(nodes, node_name, node_dict):
    _check_key_node_fields_are_filled(node_dict)
    node_tuple = NODE(**node_dict)
    nodes.update({node_name: node_tuple})


def _check_key_node_fields_are_filled(node_dict):
    for key_field in KEY_NODE_FIELDS:
        if not node_dict[key_field]:
            raise MissingKeyNodeField(
                "Value of field '{}' is missing in node {}".format(key_field, node_dict)
            )


def _read_nodes_config():
    config = configparser.ConfigParser()
    config.optionxform = str
    if not config.read(NODES_INI):
        raise IOError("Problem reading file '%s'" % NODES_INI)
    return config


def _get_node_default_config():
    return copy(NODE_DEFAULTS)


def _create_nodes_by_nodes_addresses(node_name, nodes_addresses):
    nodes = {}
    for index, node_address in enumerate(nodes_addresses, start=1):
        node_dict = _get_node_default_config()
        current_node_name = node_name + "_" + str(index)
        node_dict["Board"] = _get_board_from_node_address(node_address)
        node_dict["CPU"] = _get_cpu_from_node_address(node_address)
        node_dict["MsgTask"] = RECEIVER_MSG_TASK
        _check_fields_are_filled_and_update_nodes(nodes, current_node_name, node_dict)
    return nodes


def _get_board_from_node_address(node_address):
    node_address = format_hex(node_address)
    return "0x" + node_address[0:2]


def _get_cpu_from_node_address(node_address):
    node_address = format_hex(node_address)
    return "0x" + node_address[2:4]


def _check_cell_connected(cell_id, cell_config, component_name):
    try:
        address_value = int(cell_config[component_name], 16)
    except (KeyError, ValueError):
        pass
    else:
        if address_value == 0:
            raise CellNotConnected
    return True
